alter table public.jms_mfg_operations add column if not exists assigned_machine_id text references public.jms_mfg_machines(id), add column if not exists assigned_at timestamptz;
create table if not exists public.jms_mfg_movements (id text primary key, manufacturing_order_id text not null references public.jms_mfg_orders(id) on delete cascade, operation_id text not null references public.jms_mfg_operations(id) on delete cascade, machine_id text references public.jms_mfg_machines(id), batch_id text, roll_no integer not null, gross_kg numeric(14,3) not null check(gross_kg>=0), tube_kg numeric(14,3) not null default 0 check(tube_kg>=0), net_kg numeric(14,3) generated always as (gross_kg-tube_kg) stored, qty_pcs numeric(14,2), packs_or_cartons numeric(14,2), attributes jsonb not null default '{}'::jsonb, actor_id text, client_event_id text unique, created_at timestamptz not null default now(), unique(operation_id,roll_no), check(gross_kg>=tube_kg));
create index if not exists jms_mfg_movements_operation_idx on public.jms_mfg_movements(operation_id,roll_no);
alter table public.jms_mfg_movements enable row level security; revoke all on table public.jms_mfg_movements from anon,authenticated; grant all on table public.jms_mfg_movements to service_role;
create or replace function public.jms_mfg_add_movement(p_operation_id text,p_machine_id text,p_gross_kg numeric,p_tube_kg numeric,p_qty_pcs numeric,p_packs_or_cartons numeric,p_attributes jsonb,p_client_event_id text,p_actor_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_op public.jms_mfg_operations%rowtype; v_machine public.jms_mfg_machines%rowtype; v_roll_no integer; v_id text; v_batch_id text; v_total_net numeric; v_count integer; begin if p_gross_kg is null or p_gross_kg<=0 then raise exception 'gross_weight_required'; end if; if coalesce(p_tube_kg,0)<0 or p_gross_kg<coalesce(p_tube_kg,0) then raise exception 'invalid_tube_weight'; end if; perform pg_advisory_xact_lock(hashtext(p_operation_id)); select * into v_op from public.jms_mfg_operations where id=p_operation_id for update; if not found then raise exception 'operation_not_found'; end if; if v_op.status not in ('ready','in_progress') then raise exception 'operation_not_open'; end if; if coalesce(p_machine_id,'')<>'' then select * into v_machine from public.jms_mfg_machines where id=p_machine_id; if not found then raise exception 'machine_not_found'; end if; if not v_machine.active then raise exception 'machine_not_active'; end if; if v_machine.work_center<>v_op.work_center then raise exception 'machine_wrong_work_center'; end if; if v_op.assigned_machine_id is not null and v_op.assigned_machine_id<>p_machine_id then raise exception 'operation_assigned_to_other_machine'; end if; update public.jms_mfg_operations set assigned_machine_id=p_machine_id,assigned_at=coalesce(assigned_at,now()),updated_at=now() where id=p_operation_id; end if; if p_client_event_id is not null and exists(select 1 from public.jms_mfg_movements where client_event_id=p_client_event_id) then select roll_no into v_roll_no from public.jms_mfg_movements where client_event_id=p_client_event_id limit 1; else select coalesce(max(roll_no),0)+1 into v_roll_no from public.jms_mfg_movements where operation_id=p_operation_id; v_batch_id:=coalesce(v_op.batch_id,v_op.manufacturing_order_id||'-'||v_op.work_center||'-'||v_op.seq::text); v_id:=v_op.id||'-roll-'||lpad(v_roll_no::text,4,'0'); insert into public.jms_mfg_movements(id,manufacturing_order_id,operation_id,machine_id,batch_id,roll_no,gross_kg,tube_kg,qty_pcs,packs_or_cartons,attributes,actor_id,client_event_id) values(v_id,v_op.manufacturing_order_id,v_op.id,nullif(p_machine_id,''),v_batch_id,v_roll_no,p_gross_kg,coalesce(p_tube_kg,0),p_qty_pcs,p_packs_or_cartons,coalesce(p_attributes,'{}'::jsonb),p_actor_id,p_client_event_id); update public.jms_mfg_operations set status='in_progress',started_at=coalesce(started_at,now()),updated_at=now() where id=p_operation_id; end if; select count(*),coalesce(sum(net_kg),0) into v_count,v_total_net from public.jms_mfg_movements where operation_id=p_operation_id; return jsonb_build_object('ok',true,'roll_no',v_roll_no,'movement_count',v_count,'total_net_kg',v_total_net); end; $$;
revoke all on function public.jms_mfg_add_movement(text,text,numeric,numeric,numeric,numeric,jsonb,text,text) from public,anon,authenticated; grant execute on function public.jms_mfg_add_movement(text,text,numeric,numeric,numeric,numeric,jsonb,text,text) to service_role;
